mapper.select:
/* 설명 : 교수QNA미답변수조회 - 분리하려다 남과장에게 던지기 함. */ WITH REPLY_ATCL AS ( SELECT DISTINCT UP_ATCL_ID FROM TB_LMS_BBS_ATCL BA JOIN TB_LMS_BBS BBS ON BA.BBS_ID = BBS.BBS_ID AND BBS.DELYN = 'N' JOIN TB_LMS_SBJCT S ON S.SBJCT_ID = BBS.SBJCT_ID JOIN TB_LMS_SBJCT_ADM SA ON SA.SBJCT_ID = S.SBJCT_ID AND SA.USER_ID = BA.USER_ID WHERE 1 = 1 AND BA.DELYN = 'N' AND BA.UP_ATCL_ID IS NOT NULL AND SA.USER_ID = #{userId} ), SELECT NVL( SUM( CASE WHEN BBS.BBS_TYCD = 'QNA' THEN 1 ELSE 0 END ) , 0 )AS QNA_NOREPLY_CNT FROM TB_LMS_BBS_ATCL BA JOIN TB_LMS_BBS BBS ON BBS.BBS_ID = BA.BBS_ID AND BBS.DELYN = 'N' JOIN TB_LMS_SBJCT S ON S.SBJCT_ID = BBS.SBJCT_ID /* 교수 테이블과 학생 수강 테이블을 각각 LEFT JOIN */ LEFT JOIN TB_LMS_SBJCT_ADM SA ON SA.SBJCT_ID = S.SBJCT_ID
AND SA.USER_ID IN #{id}
LEFT JOIN REPLY_YN RP ON RP.UP_ATCL_ID = BA.ATCL_ID WHERE BA.DELYN = 'N' AND BA.UP_ATCL_ID IS NULL

/* 설 명 : 교수대시보드 게시판미열람수 조회쿼리 */ WITH REPLY_YN AS ( SELECT DISTINCT UP_ATCL_ID FROM TB_LMS_BBS_ATCL WHERE DELYN = 'N' AND UP_ATCL_ID IS NOT NULL ), READ_YN AS ( SELECT DISTINCT ATCL_ID FROM TB_LMS_BBS_ATCL_INQ_RCD WHERE VWER_ID = #{userId} ) SELECT NVL( SUM( CASE WHEN BBS.BBS_TYCD = 'NTC' THEN 1 ELSE 0 END ), 0 ) AS NOTICE_UNREAD_CNT, NVL( SUM( CASE WHEN BBS.BBS_TYCD = 'QNA' THEN 1 ELSE 0 END ) , 0 )AS QNA_NOREPLY_CNT, NVL ( SUM( CASE WHEN BBS.BBS_TYCD = '1ON1' THEN 1 ELSE 0 END ) , 0 ) AS ONE_ON_ONE_NOREPLY_CNT, NVL ( SUM( CASE WHEN BBS.BBS_TYCD = 'DATARM' THEN 1 ELSE 0 END ) , 0 ) AS DATARM_UNREAD_CNT FROM TB_LMS_BBS_ATCL BA JOIN TB_LMS_BBS BBS ON BBS.BBS_ID = BA.BBS_ID AND BBS.DELYN = 'N' JOIN TB_LMS_SBJCT S ON S.SBJCT_ID = BBS.SBJCT_ID /* 교수 테이블과 학생 수강 테이블을 각각 LEFT JOIN */ LEFT JOIN TB_LMS_SBJCT_ADM SA ON SA.SBJCT_ID = S.SBJCT_ID
AND SA.USER_ID IN #{id}
LEFT JOIN REPLY_YN RP ON RP.UP_ATCL_ID = BA.ATCL_ID LEFT JOIN READ_YN RD ON RD.ATCL_ID = BA.ATCL_ID WHERE BA.DELYN = 'N' AND BA.UP_ATCL_ID IS NULL

/* 교수대시보드모든공지목록조회 : TOPIC - PROF_DASH_ALL_NOTICE, BADGE - 전체 */ SELECT * FROM ( SELECT 'PROF_DASH_ALL_NOTICE' TOPIC, CASE WHEN BBS_TYCD = 'CRS_NTC' THEN 'ALL' ELSE 'SUBJECT' END BADGE, BBS.BBS_ID, BBS.BBS_TYCD, BA.ATCL_ID, BA.ATCL_TTL, BA.REG_DTTM, CASE WHEN EXISTS ( SELECT 1 FROM TB_LMS_BBS_ATCL_INQ_RCD R WHERE R.ATCL_ID = BA.ATCL_ID AND R.VWER_ID = #{userId} ) THEN 'Y' ELSE 'N' END READ_YN, ROW_NUMBER() OVER ( ORDER BY BA.REG_DTTM DESC ) RN, ORG.ORGNM, SC.SMSTR_CHRTNM, S.SBJCTNM, S.SBJCT_ID FROM TB_LMS_SBJCT_ADM ADM JOIN TB_LMS_SBJCT S ON ADM.SBJCT_ID = S.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT SC ON SC.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID
JOIN TB_LMS_BBS BBS ON ( BBS.SBJCT_ID = S.SBJCT_ID OR ( BBS.BBS_TYCD = 'NTC' AND BBS.BBS_ID IN ( BBS.ORG_ID || '_NTC_SBJCT', BBS.ORG_ID || '_NTC_ORG' ) ) ) AND BBS.BBS_TYCD IN ('NTC', 'CRS_NTC') AND BBS.DELYN = 'N'
AND BBS.ORG_ID = #{orgId}
JOIN TB_LMS_BBS_ATCL BA ON BBS.BBS_ID = BA.BBS_ID AND BA.DELYN = 'N' JOIN TB_LMS_ORG ORG ON ORG.ORG_ID = BBS.ORG_ID WHERE 1 = 1 AND ADM.USER_ID = #{userId} ) WHERE RN <= #{limitTop}

/* 교수대시보드과목공지목록조회 : TOPIC - PROF_DASH_SUBJECT_NOTICE, BADGE - 과목 */ SELECT * FROM ( SELECT 'PROF_DASH_SUBJECT_NOTICE' TOPIC, 'SUBJECT' BADGE, BBS.BBS_ID, BBS.BBS_TYCD, BA.ATCL_ID, BA.ATCL_TTL, BA.REG_DTTM, CASE WHEN EXISTS ( SELECT 1 FROM TB_LMS_BBS_ATCL_INQ_RCD R WHERE R.ATCL_ID = BA.ATCL_ID AND R.VWER_ID = #{userId} ) THEN 'Y' ELSE 'N' END READ_YN, ROW_NUMBER() OVER ( ORDER BY BA.REG_DTTM DESC ) RN, ORG.ORGNM, SC.SMSTR_CHRTNM, S.SBJCTNM, S.SBJCT_ID FROM TB_LMS_SBJCT_ADM ADM JOIN TB_LMS_SBJCT S ON ADM.SBJCT_ID = S.SBJCT_ID JOIN TB_LMS_SMSTR_CHRT SC ON SC.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID
JOIN TB_LMS_BBS BBS ON ( BBS.SBJCT_ID = S.SBJCT_ID OR BBS.BBS_ID = BBS.ORG_ID || '_' || BBS.BBS_TYCD || CASE WHEN BBS.BBS_TYCD = 'NTC' THEN '_SBJCT' ELSE '' END ) AND BBS.BBS_TYCD IN ('NTC', 'CRS_NTC') AND BBS.DELYN = 'N'
AND BBS.ORG_ID = #{orgId}
JOIN TB_LMS_BBS_ATCL BA ON BBS.BBS_ID = BA.BBS_ID AND BA.DELYN = 'N' JOIN TB_LMS_ORG ORG ON ORG.ORG_ID = BBS.ORG_ID WHERE 1 = 1 AND ADM.USER_ID = #{userId} ) WHERE RN <= #{limitTop}

/* 학생과목최근자료실목록조회 : TOPIC - STDNT_SUBJECT_TOP_DATARM, BADGE - 점 */ SELECT * FROM ( SELECT 'STDNT_SUBJECT_TOP_DATARM' TOPIC, 'DOT' BADGE, BBS.BBS_ID, BBS.BBS_TYCD, BA.ATCL_ID, BA.ATCL_TTL, BA.REG_DTTM, CASE WHEN EXISTS ( SELECT 1 FROM TB_LMS_BBS_ATCL_INQ_RCD R WHERE R.ATCL_ID = BA.ATCL_ID AND R.VWER_ID = #{userId} ) THEN 'Y' ELSE 'N' END READ_YN, ROW_NUMBER() OVER ( ORDER BY BA.REG_DTTM DESC ) RN, ORG.ORGNM, SC.SMSTR_CHRTNM, S.SBJCTNM, S.SBJCT_ID FROM TB_LMS_SBJCT S JOIN TB_LMS_SMSTR_CHRT SC ON SC.SMSTR_CHRT_ID = S.SMSTR_CHRT_ID JOIN TB_LMS_BBS BBS ON BBS.SBJCT_ID = S.SBJCT_ID AND BBS.BBS_TYCD = 'DATARM' AND BBS.DELYN = 'N' AND BBS.ORG_ID = #{orgId} JOIN TB_LMS_BBS_ATCL BA ON BBS.BBS_ID = BA.BBS_ID AND BA.DELYN = 'N' JOIN TB_LMS_ORG ORG ON ORG.ORG_ID = BBS.ORG_ID WHERE 1 = 1
AND S.SBJCT_ID = #{sbjctId}
) WHERE RN <= #{limitTop}
